package com.crms.entity;import jakarta.persistence.*;import java.time.Instant;@Entity public class PlacementRecord{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private Student student;@ManyToOne private Company company;private String role;private Double packageLpa;private Instant placedAt=Instant.now();public Long getId(){return id;}public Student getStudent(){return student;}public void setStudent(Student v){student=v;}public Company getCompany(){return company;}public void setCompany(Company v){company=v;}public String getRole(){return role;}public void setRole(String v){role=v;}public Double getPackageLpa(){return packageLpa;}public void setPackageLpa(Double v){packageLpa=v;}public Instant getPlacedAt(){return placedAt;}}
